import { Base } from '@ember/object';
import { action, computed } from '@ember/object';
import { inject as service } from '@ember/service';
import { tracked } from '@glimmer/tracking';
import { assert } from '@ember/debug';

/**
  @module
  @class
  @public
*/
export default class NavItem extends Base {
	/**
	 *
	 * @property
	 * @private
	 */
	@tracked
	_isCollapsed = true;

	/**
	 *
	 * @service
	 * @private
	 */
	@service
	media;

	/**
	 *
	 * @computed
	 * @private
	 * @param {*} name
	 */
	@computed('_isCollapsed', 'isMobile')
	get isExpanded() {
		return !this._isCollapsed && this.isMobile;
	}

	/**
	 *
	 * @computed
	 * @private
	 */
	get isMobile() {
		return this.media.isMobile;
	}

	/**
	 *
	 * @action
	 * @private
	 * @param {Event} event
	 */
	@action
	toggle(event) {
		assert('NavItem expects an event', event && event instanceof Event);
		this._isCollapsed = !this._isCollapsed;
	}
}

export const { toggle } = NavItem.prototype;

